(function(){
  'use strict';
  const R=window.Rewards,P=window.Planning;
  const rarity={bronze:'Бронза',silver:'Серебро',gold:'Золото',legendary:'Легендарная'};
  let scanTimer=null,showTimer=null,muted=true,active=false,queue=[],previewMode=false;
  function game(){return P.achievements({goals:state.goals,transactions:state.transactions,month:currentMonth,subscriptions:state.subscriptions||[],budgets:state.budgets,today:localDate(),play:state.play||{}});}
  function writeLog(){muted=true;persist();muted=false;}
  function ensureLog(){try{R.validate(state.rewards);}catch{delete state.rewards;}const result=R.reconcile(state.rewards,game());state.rewards=result.log;return result.events;}
  function schedule(){if(muted)return;clearTimeout(scanTimer);scanTimer=setTimeout(collect,0);}
  function collect(){scanTimer=null;const before=JSON.stringify(state.rewards),events=ensureLog();if(JSON.stringify(state.rewards)!==before)writeLog();queue.push(...events);decorate();showNext();}
  function confetti(){return '<div class="reward-confetti" aria-hidden="true">'+Array.from({length:24},(_,i)=>'<i style="--x:'+((i*37)%100)+'%;--drift:'+((i%2?-1:1)*(20+i*3))+'px;--delay:'+((i%6)*.12)+'s;--rotation:'+(i*47)+'deg;--confetti-color:'+['#c6e2a1','#dab666','#ac94c5','#94b6a1'][i%4]+'"></i>').join('')+'</div>';}
  function celebrationMarkup(event){const isLevel=event.type==='level',b=event.badge,avatar=isLevel?R.avatars.find(a=>a.level===event.level):null;return confetti()+'<div class="reward-halo" aria-hidden="true"></div><span class="reward-eyebrow">'+(event.preview?'Предпросмотр поздравления':isLevel?'Новая глава твоей истории':'Ещё одна маленькая победа')+'</span><div class="reward-stage '+(isLevel?'level-reward':b.tier)+'">'+(isLevel?R.avatarSVG(avatar,'celebration'):R.medalSVG(b,'celebration'))+'<span class="reward-spark s1">✦</span><span class="reward-spark s2">✧</span><span class="reward-spark s3">✦</span></div><span class="reward-kind">'+(isLevel?'Уровень '+event.level:rarity[b.tier]+' · '+esc(b.group))+'</span><h2 id="reward-title">'+(isLevel?'Новый уровень!':'Достижение твоё!')+'</h2><h3>'+esc(isLevel?event.levelName:b.title)+'</h3><p class="reward-description">'+(isLevel?'Твой аватар эволюционировал в персонажа «'+esc(avatar.name)+'». Каждый шаг к цели делает тебя сильнее.':esc(b.description))+'</p><div class="reward-prize">'+(isLevel?'<span>НОВЫЙ АВАТАР</span><strong>'+esc(avatar.name)+'</strong>':'<span>ОПЫТ ЗА ДОСТИЖЕНИЕ</span><strong>＋'+b.xp+' <small>XP</small></strong>')+'</div><button class="button primary reward-continue" data-reward-next>'+((queue.length>0&&!event.preview)?'Здорово! Дальше →':'Отлично! Продолжить')+'</button><div class="reward-bottom"><span>'+(event.preview?'Предпросмотр не начисляет XP':queue.length?'Ещё поздравлений: '+queue.length:'Продолжай в своём темпе')+'</span><button class="link-button" data-reward-skip>'+((queue.length>0&&!event.preview)?'Пропустить остальные':'Закрыть')+'</button></div>';}
  function showNext(){if(active||!queue.length)return;clearTimeout(showTimer);const form=$('#modal');if(form?.open){showTimer=setTimeout(showNext,200);return;}const dialog=$('#reward-dialog');const event=queue.shift();previewMode=!!event.preview;$('#reward-content').innerHTML=celebrationMarkup(event);active=true;dialog.showModal();}
  function next(){active=false;if(queue.length){$('#reward-content').innerHTML=celebrationMarkup(queue.shift());active=true;}else $('#reward-dialog').close();}
  function closeAll(){queue=[];active=false;$('#reward-dialog').close();}
  function preview(kind='badge'){if(active)return;const a=game();const event=kind==='level'?{type:'level',level:R.rank(a.xp),levelName:a.level.name,xp:a.xp,preview:true}:{type:'badge',badge:a.badges.find(b=>b.earned)||a.badges[0],preview:true};queue.push(event);showNext();}
  function badgeCard(b){const current=b.unit==='₸'?money(b.current):b.unit==='%'?b.current.toFixed(1)+'%':Math.min(b.current,b.target),target=b.unit==='₸'?money(b.target):b.target+(b.unit&&b.unit!=='%'?' '+b.unit:b.unit||'');const left=b.unit==='₸'?money(Math.max(0,b.target-b.current)):b.unit==='%'?Math.max(0,b.target-b.current).toFixed(1)+' п.п.':Math.max(0,b.target-b.current)+(b.unit?' '+b.unit:'');return '<article class="panel achievement-card award-card '+b.tier+' '+(b.earned?'earned':'locked')+'"><div class="award-card-top"><span class="award-rarity"><i></i>'+rarity[b.tier]+'</span><span class="award-points">'+b.xp+' XP</span></div><div class="award-visual">'+R.medalSVG(b)+'</div><div class="award-copy"><span class="badge-group-label">'+esc(b.group)+'</span><h3>'+esc(b.title)+'</h3><p>'+esc(b.description)+'</p></div><div class="award-card-bottom"><div class="award-numbers"><span>'+current+'</span><span>'+target+'</span></div><div class="progress"><div style="width:'+b.progress*100+'%"></div></div><div class="award-state">'+(b.earned?'<span class="earned-tick">✓</span> Получено':b.target===1?'<span>◇</span> Выполни условие выше':'<span>◇</span> Осталось '+left)+'</div>'+(b.earned?'<button class="award-replay" data-replay-award="'+b.id+'" aria-label="Посмотреть поздравление: '+esc(b.title)+'">Посмотреть поздравление ↗</button>':'<div class="award-locked-label">Награда ждёт тебя</div>')+'</div></article>';}
  function profile(){const a=game(),rank=R.rank(a.xp),avatar=R.activeAvatar(state.rewards,a.xp),nextAvatar=R.avatars.find(v=>v.level===rank+1);return heading('Твой персонаж растёт вместе с тобой.','Аватар меняется автоматически при переходе на новый уровень.', '<button class="button secondary" data-preview-level>✧ Посмотреть поздравление</button>')+'<section class="player-profile panel"><div class="player-portrait">'+R.avatarSVG(avatar,'profile')+'<span class="portrait-rank">'+rank+'</span></div><div class="player-profile-copy"><div class="eyebrow">Текущий аватар · уровень '+rank+'</div><h2>'+esc(avatar.name)+'</h2><p>'+esc(a.level.name)+' · '+a.xp+' XP</p><div class="progress"><div style="width:'+(a.nextLevel?(a.xp-a.level.min)/(a.nextLevel.min-a.level.min)*100:100)+'%"></div></div><span class="profile-next">'+(nextAvatar?'До персонажа «'+esc(nextAvatar.name)+'» — '+(a.nextLevel.min-a.xp)+' XP.':'Ты достиг финальной эволюции персонажа.')+'</span></div><div class="profile-seal">АВТО<br><strong>ЭВОЛЮЦИЯ</strong><small>Каждый уровень —<br>новый персонаж</small></div></section><div class="collection-heading"><div><div class="eyebrow">Путь героя</div><h2>Девять ступеней роста</h2></div><span class="status-tag">Сейчас: '+rank+' из 9</span></div><div class="avatar-evolution">'+R.avatars.map(v=>'<article class="evolution-card panel '+(v.level===rank?'current':v.level<rank?'passed':'future')+'"><div class="evolution-top"><span>УРОВЕНЬ '+v.level+'</span><span>'+(v.level===rank?'●':v.level<rank?'✓':'◇')+'</span></div><div class="evolution-portrait">'+R.avatarSVG(v,'evolution')+'</div><h3>'+esc(v.name)+'</h3><p>'+R.levels[v.level-1].toLocaleString('ru')+' XP</p><div class="evolution-state">'+(v.level===rank?'Твой текущий персонаж':v.level<rank?'Пройденный этап':'До открытия: '+(R.levels[v.level-1]-a.xp).toLocaleString('ru')+' XP')+'</div></article>').join('')+'</div><div class="info-box section-gap"><strong>Выбирать аватар вручную не нужно.</strong><br>Персонаж определяется текущим уровнем и меняется автоматически. Уровень и XP рассчитываются по локальному прогрессу; изменение данных может изменить текущую ступень. Авторизации и облачного сохранения пока нет.</div>';}
  function decorate(){if(!state.rewards)return;const a=game(),avatar=R.activeAvatar(state.rewards,a.xp),rank=R.rank(a.xp);
    const top=$('#player-profile-button');if(top){top.innerHTML='<span class="top-player-art">'+R.avatarSVG(avatar,'top')+'</span><span class="top-player-label">Ур. '+rank+'</span>';top.setAttribute('aria-label','Профиль: '+avatar.name+', уровень '+rank);}
    const side=$('#sidebar-avatar');if(side)side.innerHTML=R.avatarSVG(avatar,'sidebar');const sideLabel=$('#sidebar-profile-label');if(sideLabel)sideLabel.innerHTML='Мой персонаж<small>'+esc(avatar.name)+' · уровень '+rank+'</small>';
    const hero=document.querySelector('.achievement-emblem');if(hero){hero.classList.add('player-emblem');hero.innerHTML='<button data-open-player aria-label="Мой аватар: '+esc(avatar.name)+'">'+R.avatarSVG(avatar,'hero')+'<span>УРОВЕНЬ '+rank+'</span></button>';}
    const toolbar=document.querySelector('.collection-toolbar');if(page==='achievements'&&toolbar&&!document.querySelector('[data-preview-award]')){const button=document.createElement('button');button.className='button secondary award-preview-button';button.dataset.previewAward='true';button.textContent='✧ Как выглядит награда';toolbar.appendChild(button);}
  }
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-reward-next'))next();if(b.hasAttribute('data-reward-skip'))closeAll();if(b.hasAttribute('data-preview-award'))preview();if(b.hasAttribute('data-preview-level'))preview('level');if(b.hasAttribute('data-open-player'))navigate('profile');if(b.dataset.replayAward){const badge=game().badges.find(x=>x.id===b.dataset.replayAward&&x.earned);if(badge&&!active){queue.push({type:'badge',badge,preview:true});showNext();}}});
  $('#reward-dialog').addEventListener('cancel',event=>{event.preventDefault();closeAll();});
  const initial=ensureLog();queue.push(...initial);window.CashualRewards={schedule,decorate,badgeCard,profile};window.CashualGrowth.pages.profile=profile;navItems.splice(navItems.findIndex(x=>x[0]==='achievements')+1,0,['profile','Мой персонаж','users']);if(location.hash==='#profile')page='profile';writeLog();render();muted=false;if(queue.length)showTimer=setTimeout(showNext,350);
})();
